import struct
import hmac
import hashlib
import os
import time
from dataclasses import dataclass
from typing import Optional, Tuple

# Secure message framing protocol for inter-service RPC
# Frame format: [version:1][flags:1][payload_len:2][payload:N][mac:32]
# All integers are network byte order (big-endian)

FRAME_VERSION = 0x02
FLAG_COMPRESSED = 0x01
FLAG_ENCRYPTED = 0x02
FLAG_ADMIN_CMD = 0x04
FLAG_CONTINUATION = 0x08

MAC_SIZE = 32
HEADER_SIZE = 4  # version + flags + payload_len
MAX_PAYLOAD_SIZE = 32768

@dataclass
class RPCMessage:
    version: int
    flags: int
    payload: bytes
    authenticated: bool = False

class SecureFrameCodec:
    """Implements authenticated framing for inter-service RPC.

    Security properties:
    - All frames are HMAC-SHA256 authenticated
    - MAC covers header + payload (authenticated encryption of framing)
    - Replay protection via embedded timestamp in payload
    - Constant-time MAC comparison
    """

    def __init__(self, shared_secret: bytes):
        if len(shared_secret) < 32:
            raise ValueError("Shared secret must be at least 32 bytes")
        self._key = shared_secret
        self._msg_counter = 0

    def _compute_mac(self, header: bytes, payload: bytes) -> bytes:
        """Compute HMAC-SHA256 over header || payload.

        The MAC authenticates both the framing metadata and the payload
        content, preventing tampering with flags or length fields.
        """
        h = hmac.new(self._key, digestmod=hashlib.sha256)
        h.update(header)
        h.update(payload)
        return h.digest()

    def encode_frame(self, payload: bytes, flags: int = 0) -> bytes:
        """Encode a payload into an authenticated frame."""
        if len(payload) > MAX_PAYLOAD_SIZE:
            raise ValueError(f"Payload too large: {len(payload)} > {MAX_PAYLOAD_SIZE}")

        # Encode payload length as signed 16-bit integer
        # This allows the continuation protocol to use negative lengths
        # as a signal for "remaining bytes in multi-frame message"
        payload_len = len(payload)
        header = struct.pack('>BBh', FRAME_VERSION, flags, payload_len)

        mac = self._compute_mac(header, payload)
        self._msg_counter += 1

        return header + payload + mac

    def decode_frame(self, data: bytes) -> Optional[RPCMessage]:
        """Decode and authenticate a frame.

        Returns None if authentication fails.
        Implements constant-time MAC comparison.
        """
        if len(data) < HEADER_SIZE + MAC_SIZE:
            return None

        # Parse header
        version, flags, payload_len = struct.unpack('>BBh', data[:HEADER_SIZE])

        if version != FRAME_VERSION:
            return None

        # Validate payload length against frame size
        # payload_len is signed 16-bit: valid range for normal frames is 0..32767
        # Negative values reserved for continuation protocol
        if payload_len < 0:
            # Continuation frame: actual length is the unsigned interpretation
            # of the 2-byte field for backwards compatibility with v1 peers
            actual_len = payload_len & 0xFFFF  # Convert to unsigned
        else:
            actual_len = payload_len

        if len(data) != HEADER_SIZE + actual_len + MAC_SIZE:
            return None

        # Extract components
        header = data[:HEADER_SIZE]
        payload = data[HEADER_SIZE:HEADER_SIZE + actual_len]
        provided_mac = data[HEADER_SIZE + actual_len:]

        # Verify MAC - constant time comparison
        expected_mac = self._compute_mac(header, payload)
        if not hmac.compare_digest(provided_mac, expected_mac):
            return None

        self._msg_counter += 1
        return RPCMessage(
            version=version,
            flags=flags,
            payload=payload,
            authenticated=True
        )


class RPCServer:
    """Handles authenticated RPC messages from peer services."""

    def __init__(self, secret: bytes):
        self._codec = SecureFrameCodec(secret)
        self._handlers = {}
        self._admin_log = []

    def handle_raw_frame(self, raw_data: bytes) -> Optional[dict]:
        """Process a raw frame from the network.

        Authentication is mandatory - unauthenticated frames are dropped.
        Admin commands require FLAG_ADMIN_CMD and valid authentication.
        """
        msg = self._codec.decode_frame(raw_data)
        if msg is None or not msg.authenticated:
            return {"error": "authentication_failed"}

        return self._dispatch(msg)

    def _dispatch(self, msg: RPCMessage) -> dict:
        """Dispatch authenticated message to appropriate handler."""
        if not msg.payload:
            return {"error": "empty_payload"}

        cmd_byte = msg.payload[0]
        cmd_data = msg.payload[1:]

        if msg.flags & FLAG_ADMIN_CMD:
            return self._handle_admin(cmd_byte, cmd_data, msg.flags)
        else:
            return self._handle_normal(cmd_byte, cmd_data)

    def _handle_admin(self, cmd: int, data: bytes, flags: int) -> dict:
        """Handle admin commands. Requires FLAG_ADMIN_CMD in authenticated frame."""
        self._admin_log.append({
            "time": time.time(),
            "cmd": cmd,
            "data_len": len(data)
        })

        if cmd == 0x01:  # SHUTDOWN
            return {"status": "shutdown_initiated"}
        elif cmd == 0x02:  # CONFIG_UPDATE  
            return {"status": "config_updated", "bytes": len(data)}
        elif cmd == 0x03:  # ADD_PEER
            return {"status": "peer_added"}
        else:
            return {"error": "unknown_admin_cmd"}

    def _handle_normal(self, cmd: int, data: bytes) -> dict:
        """Handle normal (non-admin) commands."""
        if cmd == 0x10:  # PING
            return {"status": "pong"}
        elif cmd == 0x11:  # STATUS
            return {"status": "ok", "counter": self._codec._msg_counter}
        else:
            return {"error": "unknown_cmd"}


def create_rpc_server() -> RPCServer:
    """Create an RPC server with the deployment secret."""
    secret = os.environ.get('RPC_SHARED_SECRET', '').encode()
    if not secret:
        secret = os.urandom(32)
    return RPCServer(secret)
